window.PROBLEMS=[
{
"id": "q1",
"tier": "easy",
"topic": "aggregation",
"title": "Policies per product",
"prompt": "Count policies per product, highest count first.",
"hint": "GROUP BY product, ORDER BY the count.",
"solution": "SELECT product, COUNT(*) AS n FROM policies GROUP BY product ORDER BY n DESC, product;",
"explanation": "Basic GROUP BY. Tie-break on product so the order is deterministic.",
"ordered": true
},
{
"id": "q2",
"tier": "easy",
"topic": "aggregation",
"title": "Total premium by state",
"prompt": "Return each state and total written premium (rounded to 2 dp).",
"hint": "SUM + ROUND.",
"solution": "SELECT state, ROUND(SUM(premium),2) AS total_premium FROM policies GROUP BY state ORDER BY state;",
"explanation": "Aggregate then round \u2014 rounding before summing loses precision.",
"ordered": true
},
{
"id": "q3",
"tier": "easy",
"topic": "filtering",
"title": "Open claims over $3k reserve",
"prompt": "List claim_id, reserve_amount for OPEN claims whose reserve exceeds 3000.",
"hint": "WHERE with two conditions.",
"solution": "SELECT claim_id, reserve_amount FROM claims WHERE status='OPEN' AND reserve_amount>3000 ORDER BY claim_id;",
"explanation": "Straight filter. Watch string case on status.",
"ordered": true
},
{
"id": "q4",
"tier": "easy",
"topic": "joins",
"title": "Claims with product",
"prompt": "For each claim show claim_id, product and paid_amount.",
"hint": "Join claims to policies on policy_id.",
"solution": "SELECT c.claim_id, p.product, c.paid_amount FROM claims c JOIN policies p ON p.policy_id=c.policy_id ORDER BY c.claim_id;",
"explanation": "INNER JOIN on the foreign key.",
"ordered": true
},
{
"id": "q5",
"tier": "easy",
"topic": "joins",
"title": "Customers with no claims",
"prompt": "Return names of customers who have never had a claim.",
"hint": "LEFT JOIN through policies to claims and keep NULLs \u2014 or NOT EXISTS.",
"solution": "SELECT name FROM customers cu WHERE NOT EXISTS (SELECT 1 FROM policies p JOIN claims c ON c.policy_id=p.policy_id WHERE p.customer_id=cu.customer_id) ORDER BY name;",
"explanation": "Anti-join. NOT EXISTS is NULL-safe; NOT IN breaks if the subquery returns a NULL.",
"ordered": true
},
{
"id": "q6",
"tier": "easy",
"topic": "aggregation",
"title": "Average claim severity by cause",
"prompt": "Average incurred (paid + reserve) per cause, 2 dp, sorted by average desc.",
"hint": "Incurred = paid_amount + reserve_amount.",
"solution": "SELECT cause, ROUND(AVG(paid_amount+reserve_amount),2) AS avg_incurred FROM claims GROUP BY cause ORDER BY avg_incurred DESC;",
"explanation": "Severity = loss per claim.",
"ordered": true
},
{
"id": "q7",
"tier": "easy",
"topic": "having",
"title": "States with 3+ customers",
"prompt": "States that have at least 3 customers.",
"hint": "HAVING filters after grouping.",
"solution": "SELECT state, COUNT(*) AS n FROM customers GROUP BY state HAVING COUNT(*)>=3 ORDER BY state;",
"explanation": "WHERE filters rows, HAVING filters groups.",
"ordered": true
},
{
"id": "q8",
"tier": "easy",
"topic": "dates",
"title": "Claims reported same week",
"prompt": "Claims where report_date is within 7 days of loss_date. Return claim_id and lag_days.",
"hint": "julianday(a)-julianday(b) in SQLite (DATEDIFF elsewhere).",
"solution": "SELECT claim_id, CAST(julianday(report_date)-julianday(loss_date) AS INT) AS lag_days FROM claims WHERE julianday(report_date)-julianday(loss_date)<=7 ORDER BY claim_id;",
"explanation": "Date arithmetic is dialect-specific: Databricks datediff(end,start), Snowflake DATEDIFF('day',start,end).",
"ordered": true
},
{
"id": "q9",
"tier": "easy",
"topic": "dates",
"title": "Quotes per month",
"prompt": "Count quotes per month (YYYY-MM).",
"hint": "strftime('%Y-%m', quote_date).",
"solution": "SELECT strftime('%Y-%m',quote_date) AS month, COUNT(*) AS quotes FROM quotes GROUP BY month ORDER BY month;",
"explanation": "date_trunc('month', d) in Databricks/Postgres.",
"ordered": true
},
{
"id": "q10",
"tier": "easy",
"topic": "case",
"title": "Bind rate by product",
"prompt": "Quote-to-bind rate per product as a percentage with 1 dp.",
"hint": "AVG of a 0/1 flag is a rate.",
"solution": "SELECT product, ROUND(100.0*AVG(bound),1) AS bind_rate_pct FROM quotes GROUP BY product ORDER BY product;",
"explanation": "AVG(flag) = SUM(flag)/COUNT(*). Multiply by 100.0 to avoid integer division.",
"ordered": true
},
{
"id": "q11",
"tier": "easy",
"topic": "case",
"title": "Bucket premiums",
"prompt": "Count policies in buckets: '<1000', '1000-2499', '2500+'.",
"hint": "CASE WHEN inside GROUP BY.",
"solution": "SELECT CASE WHEN premium<1000 THEN '<1000' WHEN premium<2500 THEN '1000-2499' ELSE '2500+' END AS bucket, COUNT(*) AS n FROM policies GROUP BY bucket ORDER BY bucket;",
"explanation": "CASE evaluates top-down, so the second branch only sees premium>=1000.",
"ordered": true
},
{
"id": "q12",
"tier": "easy",
"topic": "distinct",
"title": "Distinct customers with orders",
"prompt": "How many distinct users have placed a complete order?",
"hint": "COUNT(DISTINCT ...).",
"solution": "SELECT COUNT(DISTINCT user_id) AS buyers FROM orders WHERE status='complete';",
"explanation": "COUNT(DISTINCT) vs COUNT(*) is a classic interview trap.",
"ordered": false
},
{
"id": "q13",
"tier": "easy",
"topic": "joins",
"title": "Employee and manager",
"prompt": "Show each employee name with their manager's name (NULL for the top).",
"hint": "Self join employees to employees.",
"solution": "SELECT e.name, m.name AS manager FROM employees e LEFT JOIN employees m ON m.emp_id=e.manager_id ORDER BY e.emp_id;",
"explanation": "LEFT JOIN keeps the CEO with no manager.",
"ordered": true
},
{
"id": "q14",
"tier": "easy",
"topic": "aggregation",
"title": "Highest salary per department",
"prompt": "Max salary per dept.",
"hint": "GROUP BY dept.",
"solution": "SELECT dept, MAX(salary) AS max_salary FROM employees GROUP BY dept ORDER BY dept;",
"explanation": "To get the *person*, you need a window function (see medium).",
"ordered": true
},
{
"id": "q15",
"tier": "easy",
"topic": "null",
"title": "Coalesce referrals",
"prompt": "List customer name and referrer's customer_id, showing 0 when not referred.",
"hint": "COALESCE.",
"solution": "SELECT name, COALESCE(referred_by,0) AS referrer FROM customers ORDER BY customer_id;",
"explanation": "COALESCE returns the first non-NULL argument.",
"ordered": true
},
{
"id": "q16",
"tier": "easy",
"topic": "filtering",
"title": "Active policies in CA or TX",
"prompt": "policy_id of ACTIVE policies in CA or TX.",
"hint": "IN list.",
"solution": "SELECT policy_id FROM policies WHERE status='ACTIVE' AND state IN ('CA','TX') ORDER BY policy_id;",
"explanation": "Parenthesize OR conditions; IN avoids the precedence bug.",
"ordered": true
},
{
"id": "q17",
"tier": "easy",
"topic": "aggregation",
"title": "Refund share",
"prompt": "Percent of orders refunded (1 dp).",
"hint": "SUM(CASE WHEN ...)/COUNT(*).",
"solution": "SELECT ROUND(100.0*SUM(CASE WHEN status='refunded' THEN 1 ELSE 0 END)/COUNT(*),1) AS refund_pct FROM orders;",
"explanation": "Conditional aggregation.",
"ordered": false
},
{
"id": "q18",
"tier": "easy",
"topic": "union",
"title": "All customer touchpoint dates",
"prompt": "One column of distinct dates when any customer either got a quote or had a policy start, earliest 5.",
"hint": "UNION dedupes, UNION ALL doesn't.",
"solution": "SELECT d FROM (SELECT quote_date AS d FROM quotes UNION SELECT effective_date FROM policies) ORDER BY d LIMIT 5;",
"explanation": "UNION removes duplicates (costly on big data); use UNION ALL when you know rows are distinct.",
"ordered": true
},
{
"id": "q19",
"tier": "easy",
"topic": "aggregation",
"title": "Users per country and plan",
"prompt": "Count users by country and plan.",
"hint": "GROUP BY two columns.",
"solution": "SELECT country, plan, COUNT(*) AS n FROM users GROUP BY country, plan ORDER BY country, plan;",
"explanation": "Multi-column grouping.",
"ordered": true
},
{
"id": "q20",
"tier": "easy",
"topic": "subquery",
"title": "Above-average premium",
"prompt": "Policies with premium above the overall average.",
"hint": "Scalar subquery.",
"solution": "SELECT policy_id, premium FROM policies WHERE premium>(SELECT AVG(premium) FROM policies) ORDER BY policy_id;",
"explanation": "Scalar subquery evaluated once.",
"ordered": true
},
{
"id": "q21",
"tier": "medium",
"topic": "window",
"title": "Rank policies by premium within state",
"prompt": "Return state, policy_id, premium, and dense rank of premium (highest=1) within state.",
"hint": "DENSE_RANK() OVER (PARTITION BY ... ORDER BY ... DESC).",
"solution": "SELECT state, policy_id, premium, DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC) AS rnk FROM policies ORDER BY state, rnk, policy_id;",
"explanation": "ROW_NUMBER: unique; RANK: gaps after ties; DENSE_RANK: no gaps.",
"ordered": true
},
{
"id": "q22",
"tier": "medium",
"topic": "top-n",
"title": "Top 2 earners per department",
"prompt": "Name, dept, salary of the top 2 salaries per dept.",
"hint": "Rank in a CTE then filter rnk<=2 (QUALIFY in Databricks/Snowflake).",
"solution": "WITH r AS (SELECT name, dept, salary, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) rn FROM employees) SELECT name, dept, salary FROM r WHERE rn<=2 ORDER BY dept, salary DESC;",
"explanation": "Top-N per group = window rank + filter. You cannot filter a window in WHERE of the same SELECT.",
"ordered": true
},
{
"id": "q23",
"tier": "medium",
"topic": "running",
"title": "Running premium by effective date",
"prompt": "For each policy in effective_date order, show cumulative premium.",
"hint": "SUM() OVER (ORDER BY ... ROWS UNBOUNDED PRECEDING).",
"solution": "SELECT policy_id, effective_date, premium, ROUND(SUM(premium) OVER (ORDER BY effective_date, policy_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),2) AS running FROM policies ORDER BY effective_date, policy_id;",
"explanation": "Explicit ROWS frame avoids RANGE tie behavior.",
"ordered": true
},
{
"id": "q24",
"tier": "medium",
"topic": "lag",
"title": "Renewal premium change",
"prompt": "For each renewal (a customer's next policy of the same product), show customer_id, policy_id, prior premium, and % change (1 dp).",
"hint": "LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date).",
"solution": "WITH x AS (SELECT customer_id, policy_id, premium, LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date) AS prev FROM policies) SELECT customer_id, policy_id, prev, ROUND(100.0*(premium-prev)/prev,1) AS pct_change FROM x WHERE prev IS NOT NULL ORDER BY customer_id, policy_id;",
"explanation": "Rate-change analysis on renewals \u2014 a core pricing metric.",
"ordered": true
},
{
"id": "q25",
"tier": "medium",
"topic": "dedup",
"title": "Dedupe logins",
"prompt": "Return each user's distinct login dates count vs raw rows count.",
"hint": "COUNT(*) vs COUNT(DISTINCT login_date).",
"solution": "SELECT user_id, COUNT(*) AS raw_rows, COUNT(DISTINCT login_date) AS distinct_days FROM logins GROUP BY user_id ORDER BY user_id;",
"explanation": "Detect duplication before you fix it.",
"ordered": true
},
{
"id": "q26",
"tier": "medium",
"topic": "dedup",
"title": "Keep latest claim per policy",
"prompt": "For each policy keep only the most recently reported claim (tie-break on claim_id desc).",
"hint": "ROW_NUMBER() ... = 1.",
"solution": "WITH r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY policy_id ORDER BY report_date DESC, claim_id DESC) rn FROM claims) SELECT policy_id, claim_id, report_date FROM r WHERE rn=1 ORDER BY policy_id;",
"explanation": "The canonical dedup pattern (CDC, late-arriving duplicates).",
"ordered": true
},
{
"id": "q27",
"tier": "medium",
"topic": "joins",
"title": "Loss ratio by product",
"prompt": "Loss ratio = sum(paid+reserve)/sum(premium) per product, 3 dp. Aggregate claims and premium separately first.",
"hint": "Fan-out trap: joining policies to claims duplicates premium.",
"solution": "WITH prem AS (SELECT product, SUM(premium) p FROM policies GROUP BY product), loss AS (SELECT p.product, SUM(c.paid_amount+c.reserve_amount) l FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.product) SELECT prem.product, ROUND(COALESCE(l,0)/p,3) AS loss_ratio FROM prem LEFT JOIN loss ON loss.product=prem.product ORDER BY prem.product;",
"explanation": "Aggregate each fact to the shared grain before joining (drill-across). Here premium is written, not earned \u2014 say so in an interview.",
"ordered": true
},
{
"id": "q28",
"tier": "medium",
"topic": "pivot",
"title": "Claims by cause pivot",
"prompt": "One row per product with columns water, fire, theft, injury, collision = claim counts.",
"hint": "SUM(CASE WHEN cause='Water' THEN 1 ELSE 0 END).",
"solution": "SELECT p.product, SUM(CASE WHEN cause='Water' THEN 1 ELSE 0 END) water, SUM(CASE WHEN cause='Fire' THEN 1 ELSE 0 END) fire, SUM(CASE WHEN cause='Theft' THEN 1 ELSE 0 END) theft, SUM(CASE WHEN cause='Injury' THEN 1 ELSE 0 END) injury, SUM(CASE WHEN cause='Collision' THEN 1 ELSE 0 END) collision FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.product ORDER BY p.product;",
"explanation": "Conditional aggregation pivot works everywhere; Databricks also has PIVOT.",
"ordered": true
},
{
"id": "q29",
"tier": "medium",
"topic": "window",
"title": "Share of state premium",
"prompt": "Each policy's premium as % of its state's total (1 dp).",
"hint": "SUM(premium) OVER (PARTITION BY state).",
"solution": "SELECT policy_id, state, ROUND(100.0*premium/SUM(premium) OVER (PARTITION BY state),1) AS pct_of_state FROM policies ORDER BY state, policy_id;",
"explanation": "Window aggregates keep row detail \u2014 no self-join needed.",
"ordered": true
},
{
"id": "q30",
"tier": "medium",
"topic": "dates",
"title": "Monthly revenue with MoM growth",
"prompt": "Monthly complete-order revenue and MoM % growth (1 dp).",
"hint": "Aggregate in CTE, then LAG.",
"solution": "WITH m AS (SELECT strftime('%Y-%m',order_date) mon, SUM(amount) rev FROM orders WHERE status='complete' GROUP BY mon) SELECT mon, ROUND(rev,2) rev, ROUND(100.0*(rev-LAG(rev) OVER (ORDER BY mon))/LAG(rev) OVER (ORDER BY mon),1) AS mom_pct FROM m ORDER BY mon;",
"explanation": "Aggregate first, window second.",
"ordered": true
},
{
"id": "q31",
"tier": "medium",
"topic": "self-join",
"title": "Customers who referred someone in another state",
"prompt": "Referrer name, referee name where states differ.",
"hint": "Self join customers on referred_by.",
"solution": "SELECT r.name AS referrer, c.name AS referee FROM customers c JOIN customers r ON r.customer_id=c.referred_by WHERE r.state<>c.state ORDER BY referrer, referee;",
"explanation": "Self joins model relationships within one entity.",
"ordered": true
},
{
"id": "q32",
"tier": "medium",
"topic": "funnel",
"title": "Event funnel",
"prompt": "Count distinct users reaching each step: visit, signup, add_to_cart, purchase.",
"hint": "COUNT(DISTINCT CASE WHEN event_type=... THEN user_id END).",
"solution": "SELECT COUNT(DISTINCT CASE WHEN event_type='visit' THEN user_id END) visit, COUNT(DISTINCT CASE WHEN event_type='signup' THEN user_id END) signup, COUNT(DISTINCT CASE WHEN event_type='add_to_cart' THEN user_id END) add_to_cart, COUNT(DISTINCT CASE WHEN event_type='purchase' THEN user_id END) purchase FROM events;",
"explanation": "Simple funnel. A strict funnel requires steps in order (see hard).",
"ordered": false
},
{
"id": "q33",
"tier": "medium",
"topic": "funnel",
"title": "Quote funnel by month",
"prompt": "Per quote month: quotes, binds, bind rate %.",
"hint": "Same as bind rate, grouped by month.",
"solution": "SELECT strftime('%Y-%m',quote_date) mon, COUNT(*) quotes, SUM(bound) binds, ROUND(100.0*SUM(bound)/COUNT(*),1) bind_pct FROM quotes GROUP BY mon ORDER BY mon;",
"explanation": "Quote metrics are day-to-day work at an insurtech.",
"ordered": true
},
{
"id": "q34",
"tier": "medium",
"topic": "subquery",
"title": "Customers above their state average premium",
"prompt": "Customers whose total premium exceeds the average customer total in their state.",
"hint": "Two levels: customer totals, then state average via window.",
"solution": "WITH t AS (SELECT c.customer_id, c.name, c.state, SUM(p.premium) tot FROM customers c JOIN policies p ON p.customer_id=c.customer_id GROUP BY c.customer_id, c.name, c.state), s AS (SELECT *, AVG(tot) OVER (PARTITION BY state) st_avg FROM t) SELECT name, state, ROUND(tot,2) tot FROM s WHERE tot>st_avg ORDER BY state, name;",
"explanation": "Correlated-subquery problems are cleaner as window aggregates.",
"ordered": true
},
{
"id": "q35",
"tier": "medium",
"topic": "window",
"title": "Second highest salary",
"prompt": "Return the second highest distinct salary overall (NULL if none).",
"hint": "DENSE_RANK = 2, or MAX where < MAX.",
"solution": "SELECT MAX(salary) AS second_highest FROM employees WHERE salary<(SELECT MAX(salary) FROM employees);",
"explanation": "Classic. DENSE_RANK version generalizes to Nth.",
"ordered": false
},
{
"id": "q36",
"tier": "medium",
"topic": "dates",
"title": "Days since last claim per customer",
"prompt": "For each customer with claims: last loss_date and days from it to 2026-06-30.",
"hint": "MAX then julianday diff.",
"solution": "SELECT p.customer_id, MAX(c.loss_date) last_loss, CAST(julianday('2026-06-30')-julianday(MAX(c.loss_date)) AS INT) days_since FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.customer_id ORDER BY p.customer_id;",
"explanation": "Recency features feed pricing and fraud models.",
"ordered": true
},
{
"id": "q37",
"tier": "medium",
"topic": "window",
"title": "Moving 3-order average",
"prompt": "Per user, 3-order moving average of amount (current + 2 prior), 2 dp.",
"hint": "AVG() OVER (... ROWS BETWEEN 2 PRECEDING AND CURRENT ROW).",
"solution": "SELECT user_id, order_id, order_date, ROUND(AVG(amount) OVER (PARTITION BY user_id ORDER BY order_date, order_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) ma3 FROM orders ORDER BY user_id, order_date, order_id;",
"explanation": "Frames: ROWS counts rows; RANGE uses value distance.",
"ordered": true
},
{
"id": "q38",
"tier": "medium",
"topic": "joins",
"title": "Products a customer never bought",
"prompt": "Every (customer, product) combination the customer has never held a policy for. Count rows only.",
"hint": "CROSS JOIN customers \u00d7 distinct products, then anti-join.",
"solution": "SELECT COUNT(*) AS gaps FROM customers c CROSS JOIN (SELECT DISTINCT product FROM policies) pr WHERE NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id=c.customer_id AND p.product=pr.product);",
"explanation": "Cross-sell opportunity list \u2014 a densification pattern.",
"ordered": false
},
{
"id": "q39",
"tier": "medium",
"topic": "case",
"title": "Policy tenure category",
"prompt": "For each customer: number of policy terms and label 'new' (1), 'renewing' (2), 'loyal' (3+).",
"hint": "COUNT then CASE.",
"solution": "SELECT customer_id, COUNT(*) terms, CASE WHEN COUNT(*)=1 THEN 'new' WHEN COUNT(*)=2 THEN 'renewing' ELSE 'loyal' END seg FROM policies GROUP BY customer_id ORDER BY customer_id;",
"explanation": "CASE over aggregates is allowed in SELECT.",
"ordered": true
},
{
"id": "q40",
"tier": "medium",
"topic": "ranking",
"title": "Percentile of claim severity",
"prompt": "Each claim's incurred and its percent_rank within cause (2 dp).",
"hint": "PERCENT_RANK().",
"solution": "SELECT claim_id, cause, paid_amount+reserve_amount incurred, ROUND(PERCENT_RANK() OVER (PARTITION BY cause ORDER BY paid_amount+reserve_amount),2) pr FROM claims ORDER BY cause, pr, claim_id;",
"explanation": "Large-loss flags often use percentile thresholds.",
"ordered": true
},
{
"id": "q41",
"tier": "medium",
"topic": "dates",
"title": "Policies in force on a date",
"prompt": "How many policies were in force on 2025-06-30 (effective <= date < expiration, not cancelled)?",
"hint": "Half-open intervals.",
"solution": "SELECT COUNT(*) in_force FROM policies WHERE effective_date<='2025-06-30' AND expiration_date>'2025-06-30' AND status<>'CANCELLED';",
"explanation": "Half-open [start, end) avoids double counting renewal days.",
"ordered": false
},
{
"id": "q42",
"tier": "medium",
"topic": "cte",
"title": "Customers whose first quote bound",
"prompt": "Customers whose earliest quote was bound.",
"hint": "ROW_NUMBER by quote_date per customer.",
"solution": "WITH f AS (SELECT customer_id, bound, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY quote_date, quote_id) rn FROM quotes) SELECT customer_id FROM f WHERE rn=1 AND bound=1 ORDER BY customer_id;",
"explanation": "First-touch analysis.",
"ordered": true
},
{
"id": "q43",
"tier": "medium",
"topic": "aggregation",
"title": "Orders per user distribution",
"prompt": "How many users placed 0,1,2,... complete orders? Include users with 0.",
"hint": "LEFT JOIN users to orders, count per user, then count users per count.",
"solution": "WITH c AS (SELECT u.user_id, COUNT(o.order_id) n FROM users u LEFT JOIN orders o ON o.user_id=u.user_id AND o.status='complete' GROUP BY u.user_id) SELECT n AS orders, COUNT(*) users FROM c GROUP BY n ORDER BY n;",
"explanation": "Put the status filter in the ON clause, otherwise the LEFT JOIN becomes INNER.",
"ordered": true
},
{
"id": "q44",
"tier": "hard",
"topic": "gaps-islands",
"title": "Login streaks",
"prompt": "Longest consecutive-day login streak per user (dedupe same-day logins).",
"hint": "date minus ROW_NUMBER days is constant within a streak.",
"solution": "WITH d AS (SELECT DISTINCT user_id, login_date FROM logins), g AS (SELECT user_id, login_date, julianday(login_date)-ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) grp FROM d), s AS (SELECT user_id, grp, COUNT(*) len FROM g GROUP BY user_id, grp) SELECT user_id, MAX(len) longest_streak FROM s GROUP BY user_id ORDER BY user_id;",
"explanation": "The canonical gaps-and-islands trick. Dedupe first or duplicates break it.",
"ordered": true
},
{
"id": "q45",
"tier": "hard",
"topic": "gaps-islands",
"title": "Continuous coverage periods",
"prompt": "Merge each customer's overlapping/adjacent policy terms into continuous coverage periods (customer_id, start, end).",
"hint": "Flag a new island when start > running MAX(end) of prior rows.",
"solution": "WITH t AS (SELECT customer_id, effective_date s, expiration_date e, MAX(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prev_end FROM policies), g AS (SELECT *, SUM(CASE WHEN prev_end IS NULL OR s>prev_end THEN 1 ELSE 0 END) OVER (PARTITION BY customer_id ORDER BY s ROWS UNBOUNDED PRECEDING) isl FROM t) SELECT customer_id, MIN(s) cover_start, MAX(e) cover_end FROM g GROUP BY customer_id, isl ORDER BY customer_id, cover_start;",
"explanation": "Interval merging \u2014 the insurance version of gaps-and-islands (continuous insurance, lapse detection).",
"ordered": true
},
{
"id": "q46",
"tier": "hard",
"topic": "cohort",
"title": "Monthly retention cohorts",
"prompt": "For users by signup month, count how many placed a complete order in month offset 0,1,2 after signup.",
"hint": "Cohort = strftime signup month; offset = month difference.",
"solution": "WITH o AS (SELECT u.user_id, strftime('%Y-%m',u.signup_date) cohort, (CAST(strftime('%Y',o.order_date) AS INT)*12+CAST(strftime('%m',o.order_date) AS INT))-(CAST(strftime('%Y',u.signup_date) AS INT)*12+CAST(strftime('%m',u.signup_date) AS INT)) k FROM users u JOIN orders o ON o.user_id=u.user_id AND o.status='complete') SELECT cohort, COUNT(DISTINCT CASE WHEN k=0 THEN user_id END) m0, COUNT(DISTINCT CASE WHEN k=1 THEN user_id END) m1, COUNT(DISTINCT CASE WHEN k=2 THEN user_id END) m2 FROM o GROUP BY cohort ORDER BY cohort;",
"explanation": "Month index = year*12+month avoids date-function differences.",
"ordered": true
},
{
"id": "q47",
"tier": "hard",
"topic": "recursive",
"title": "Org chart depth",
"prompt": "For each employee, their level (CEO=1) and the path of names from the top.",
"hint": "WITH RECURSIVE anchor = manager_id IS NULL.",
"solution": "WITH RECURSIVE t(emp_id, name, lvl, path) AS (SELECT emp_id, name, 1, name FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.emp_id, e.name, t.lvl+1, t.path||' > '||e.name FROM employees e JOIN t ON e.manager_id=t.emp_id) SELECT emp_id, name, lvl, path FROM t ORDER BY emp_id;",
"explanation": "Recursive CTE = anchor + recursive member joined to the previous iteration.",
"ordered": true
},
{
"id": "q48",
"tier": "hard",
"topic": "recursive",
"title": "Generate a date spine",
"prompt": "Generate every month-start from 2025-01-01 to 2025-12-01 and count complete orders in each (including zero months).",
"hint": "Recursive CTE adding '+1 month'.",
"solution": "WITH RECURSIVE m(d) AS (SELECT '2025-01-01' UNION ALL SELECT date(d,'+1 month') FROM m WHERE d<'2025-12-01') SELECT m.d month_start, COUNT(o.order_id) orders FROM m LEFT JOIN orders o ON strftime('%Y-%m',o.order_date)=strftime('%Y-%m',m.d) AND o.status='complete' GROUP BY m.d ORDER BY m.d;",
"explanation": "Date spines prevent missing periods in reports (dbt_utils.date_spine in dbt; sequence()/explode in Databricks).",
"ordered": true
},
{
"id": "q49",
"tier": "hard",
"topic": "funnel",
"title": "Strict ordered funnel",
"prompt": "Users who did visit \u2192 signup \u2192 add_to_cart \u2192 purchase in non-decreasing date order. Return user_ids.",
"hint": "Get MIN date per step per user, then compare.",
"solution": "WITH s AS (SELECT user_id, MIN(CASE WHEN event_type='visit' THEN event_date END) v, MIN(CASE WHEN event_type='signup' THEN event_date END) su, MIN(CASE WHEN event_type='add_to_cart' THEN event_date END) a, MIN(CASE WHEN event_type='purchase' THEN event_date END) p FROM events GROUP BY user_id) SELECT user_id FROM s WHERE v<=su AND su<=a AND a<=p ORDER BY user_id;",
"explanation": "NULL comparisons evaluate unknown \u2192 filtered out, which is what we want.",
"ordered": true
},
{
"id": "q50",
"tier": "hard",
"topic": "earned",
"title": "Earned premium in 2025",
"prompt": "Pro-rata earned premium during calendar 2025 for non-cancelled policies, total (2 dp).",
"hint": "Overlap days = max(0, min(exp,'2026-01-01') - max(eff,'2025-01-01')).",
"solution": "SELECT ROUND(SUM(premium * MAX(0, julianday(MIN(expiration_date,'2026-01-01'))-julianday(MAX(effective_date,'2025-01-01'))) / (julianday(expiration_date)-julianday(effective_date))),2) AS earned_2025 FROM policies WHERE status<>'CANCELLED';",
"explanation": "Interval overlap formula. In SQLite scalar MIN/MAX with 2 args = LEAST/GREATEST elsewhere.",
"ordered": false
},
{
"id": "q51",
"tier": "hard",
"topic": "window",
"title": "Running count of open claims",
"prompt": "For each date a claim is reported or closed... simplified: for each report_date, cumulative number of claims reported and cumulative incurred.",
"hint": "Aggregate per date, then running SUM.",
"solution": "WITH d AS (SELECT report_date, COUNT(*) n, SUM(paid_amount+reserve_amount) inc FROM claims GROUP BY report_date) SELECT report_date, SUM(n) OVER (ORDER BY report_date) cum_claims, ROUND(SUM(inc) OVER (ORDER BY report_date),2) cum_incurred FROM d ORDER BY report_date;",
"explanation": "Aggregate-then-window avoids tie issues in RANGE frames.",
"ordered": true
},
{
"id": "q52",
"tier": "hard",
"topic": "top-n",
"title": "Top cause per state by incurred",
"prompt": "For each policy state, the cause with the highest total incurred (ties: alphabetical).",
"hint": "Aggregate, then ROW_NUMBER.",
"solution": "WITH a AS (SELECT p.state, c.cause, SUM(c.paid_amount+c.reserve_amount) inc FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.state, c.cause), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY state ORDER BY inc DESC, cause) rn FROM a) SELECT state, cause, ROUND(inc,2) inc FROM r WHERE rn=1 ORDER BY state;",
"explanation": "Top-1 per group after aggregation.",
"ordered": true
},
{
"id": "q53",
"tier": "hard",
"topic": "self-join",
"title": "Overlapping policies same customer & product",
"prompt": "Pairs of policies for the same customer and product whose terms overlap.",
"hint": "Self join with a.policy_id < b.policy_id and interval overlap: a.s < b.e AND b.s < a.e.",
"solution": "SELECT a.customer_id, a.policy_id p1, b.policy_id p2 FROM policies a JOIN policies b ON a.customer_id=b.customer_id AND a.product=b.product AND a.policy_id<b.policy_id AND a.effective_date<b.expiration_date AND b.effective_date<a.expiration_date ORDER BY 1,2,3;",
"explanation": "Overlap condition is a data-quality test you'd ship as a dbt singular test.",
"ordered": true
},
{
"id": "q54",
"tier": "hard",
"topic": "dedup",
"title": "Detect near-duplicate claims",
"prompt": "Claims on the same policy with the same cause and loss dates within 3 days of each other. Return pairs.",
"hint": "Self join with ABS(julianday diff) <= 3.",
"solution": "SELECT a.claim_id c1, b.claim_id c2, a.policy_id FROM claims a JOIN claims b ON a.policy_id=b.policy_id AND a.cause=b.cause AND a.claim_id<b.claim_id AND ABS(julianday(a.loss_date)-julianday(b.loss_date))<=3 ORDER BY 1,2;",
"explanation": "Fuzzy dedup is also a fraud signal (duplicate submissions).",
"ordered": true
},
{
"id": "q55",
"tier": "hard",
"topic": "window",
"title": "Gap between policy terms",
"prompt": "For each customer's consecutive policies (by effective_date), days of gap between previous expiration and next effective (negative = overlap).",
"hint": "LAG(expiration_date).",
"solution": "WITH x AS (SELECT customer_id, policy_id, effective_date, LAG(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id) prev_exp FROM policies) SELECT customer_id, policy_id, CAST(julianday(effective_date)-julianday(prev_exp) AS INT) gap_days FROM x WHERE prev_exp IS NOT NULL ORDER BY customer_id, policy_id;",
"explanation": "Lapse analysis for retention reporting.",
"ordered": true
},
{
"id": "q56",
"tier": "hard",
"topic": "cohort",
"title": "Quote-to-bind within 30 days of signup",
"prompt": "Per customer signup year, % of customers with a bound quote within 30 days of signup.",
"hint": "Join customers to quotes with date condition in ON; COUNT DISTINCT.",
"solution": "SELECT strftime('%Y',c.signup_date) yr, COUNT(DISTINCT c.customer_id) customers, ROUND(100.0*COUNT(DISTINCT q.customer_id)/COUNT(DISTINCT c.customer_id),1) pct FROM customers c LEFT JOIN quotes q ON q.customer_id=c.customer_id AND q.bound=1 AND julianday(q.quote_date)-julianday(c.signup_date) BETWEEN 0 AND 30 GROUP BY yr ORDER BY yr;",
"explanation": "Conditions in ON keep the denominator intact.",
"ordered": true
},
{
"id": "q57",
"tier": "hard",
"topic": "window",
"title": "Median order amount per country",
"prompt": "Median complete-order amount per user country.",
"hint": "ROW_NUMBER + COUNT window; average the middle one or two.",
"solution": "WITH o AS (SELECT u.country, o.amount, ROW_NUMBER() OVER (PARTITION BY u.country ORDER BY o.amount) rn, COUNT(*) OVER (PARTITION BY u.country) n FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='complete') SELECT country, ROUND(AVG(amount),2) median FROM o WHERE rn IN ((n+1)/2,(n+2)/2) GROUP BY country ORDER BY country;",
"explanation": "Portable median; Databricks has percentile_approx / median().",
"ordered": true
},
{
"id": "q58",
"tier": "hard",
"topic": "window",
"title": "Salary vs dept average and rank gap",
"prompt": "For each employee: salary minus dept average (0 dp) and difference to the next higher salary in dept (NULL for top).",
"hint": "AVG OVER and LAG over salary DESC.",
"solution": "SELECT name, dept, salary, ROUND(salary-AVG(salary) OVER (PARTITION BY dept)) vs_avg, LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id)-salary gap_to_next FROM employees ORDER BY dept, salary DESC;",
"explanation": "Multiple windows in one SELECT.",
"ordered": true
},
{
"id": "q59",
"tier": "hard",
"topic": "pivot",
"title": "Claims development style triangle",
"prompt": "Accident year (loss_date year) \u00d7 report lag bucket (0-1d, 2-7d, 8-30d, 31+d) claim counts.",
"hint": "CASE bucketing inside conditional aggregation.",
"solution": "SELECT strftime('%Y',loss_date) ay, SUM(CASE WHEN lag<=1 THEN 1 ELSE 0 END) d0_1, SUM(CASE WHEN lag BETWEEN 2 AND 7 THEN 1 ELSE 0 END) d2_7, SUM(CASE WHEN lag BETWEEN 8 AND 30 THEN 1 ELSE 0 END) d8_30, SUM(CASE WHEN lag>30 THEN 1 ELSE 0 END) d31p FROM (SELECT loss_date, julianday(report_date)-julianday(loss_date) lag FROM claims) GROUP BY ay ORDER BY ay;",
"explanation": "Report-lag shapes reveal IBNR risk.",
"ordered": true
},
{
"id": "q60",
"tier": "hard",
"topic": "cte",
"title": "Customers whose every claim is closed",
"prompt": "Customers with at least one claim and all claims CLOSED.",
"hint": "GROUP BY + HAVING with conditional counts.",
"solution": "SELECT p.customer_id FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.customer_id HAVING SUM(CASE WHEN c.status<>'CLOSED' THEN 1 ELSE 0 END)=0 ORDER BY p.customer_id;",
"explanation": "'For all' questions \u2192 HAVING with a count of violations = 0.",
"ordered": true
},
{
"id": "q61",
"tier": "hard",
"topic": "sessionize",
"title": "Order sessions",
"prompt": "Group each user's orders into 'sessions' where a new session starts if >30 days since the previous order. Count sessions per user.",
"hint": "LAG + flag + running SUM.",
"solution": "WITH x AS (SELECT user_id, order_date, CASE WHEN julianday(order_date)-julianday(LAG(order_date) OVER (PARTITION BY user_id ORDER BY order_date, order_id))<=30 THEN 0 ELSE 1 END new_s FROM orders) SELECT user_id, SUM(new_s) sessions FROM x GROUP BY user_id ORDER BY user_id;",
"explanation": "Sessionization = gaps-and-islands with a threshold.",
"ordered": true
},
{
"id": "q62",
"tier": "hard",
"topic": "window",
"title": "First and last premium per customer",
"prompt": "Per customer: first policy premium, latest policy premium, number of terms.",
"hint": "FIRST_VALUE / LAST_VALUE (mind the frame!).",
"solution": "SELECT DISTINCT customer_id, FIRST_VALUE(premium) OVER w first_prem, LAST_VALUE(premium) OVER w last_prem, COUNT(*) OVER (PARTITION BY customer_id) terms FROM policies WINDOW w AS (PARTITION BY customer_id ORDER BY effective_date ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) ORDER BY customer_id;",
"explanation": "LAST_VALUE with the default frame returns the current row \u2014 the #1 window gotcha.",
"ordered": true
},
{
"id": "q63",
"tier": "hard",
"topic": "joins",
"title": "Customers quoted but never bound any product",
"prompt": "Customer names with \u22652 quotes and zero binds and no policies.",
"hint": "Aggregate quotes + anti-join policies.",
"solution": "SELECT c.name FROM customers c JOIN quotes q ON q.customer_id=c.customer_id GROUP BY c.customer_id, c.name HAVING COUNT(*)>=2 AND SUM(q.bound)=0 AND NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id=c.customer_id) ORDER BY c.name;",
"explanation": "Combine HAVING with correlated NOT EXISTS. Empty result is a valid answer \u2014 know why.",
"ordered": true
},
{
"id": "q64",
"tier": "hard",
"topic": "dates",
"title": "Weekly active users with 7-day rolling",
"prompt": "Per login date: distinct users that day and distinct users in the trailing 7 days.",
"hint": "Self join logins on date window, COUNT DISTINCT.",
"solution": "WITH d AS (SELECT DISTINCT login_date FROM logins) SELECT d.login_date, COUNT(DISTINCT CASE WHEN l.login_date=d.login_date THEN l.user_id END) dau, COUNT(DISTINCT l.user_id) wau7 FROM d JOIN logins l ON julianday(l.login_date) BETWEEN julianday(d.login_date)-6 AND julianday(d.login_date) GROUP BY d.login_date ORDER BY d.login_date;",
"explanation": "COUNT DISTINCT over a rolling window isn't supported as a window function in most engines \u2014 use a range self join.",
"ordered": true
}
];
